			const nextStrategy = useLocalFileWorkflow ? "localFile" : isVkCdnContext ? VK_AUDIO_STRATEGY : this.videoHandler.site.host === "yandexdisk" ? "yandexDisk" : this.videoHandler.site.host === "douyin" ? DOUYIN_AUDIO_STRATEGY : this.videoHandler.site.host === "youtube" ? WEB_ABR_STRATEGY : YT_AUDIO_STRATEGY;
			if (this.audioDownloader.strategy === nextStrategy) return;
